#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) {
        res *= i;
    }
    return res;
}

long long A(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> current_z(1, 1);
    long long result_sum = 0;
    for (int i = 2; i <= n; ++i) {
        int size_new_z = (i * i) / 2;
        vector<long long> new_z(size_new_z, 0);
        for (size_t j = 0; j < current_z.size(); ++j) {
            for (int k = 0; k < i; ++k) {
                if (current_z[j] > 0) {
                    new_z[i - k - 1 + j] += current_z[j];
                }
            }
        }
        vector<long long> prefix(current_z.size() + 1, 0);
        for (int w = (int)current_z.size() - 1; w >= 0; --w) {
            prefix[w] = (prefix[w + 1] + current_z[w]) % mod;
        }
        vector<long long> e_arr(prefix.size(), 0);
        vector<long long> f_arr(prefix.size(), 0);
        for (size_t w = 0; w + 1 < prefix.size(); ++w) {
            e_arr[w + 1] = (e_arr[w] + prefix[w]) % mod;
            f_arr[w + 1] = (f_arr[w] - (long long)w * prefix[w]) % mod;
        }
        long long temp = 0;
        for (size_t jj = 0; jj < current_z.size(); ++jj) {
            int L = jj + 2;
            int R = min((int)current_z.size() - 1, i + (int)jj);
            long long ccc = 0;
            if (R >= L) {
                ccc = ((e_arr[R + 1] - e_arr[L]) * (i + 1 + (int)jj) + (f_arr[R + 1] - f_arr[L])) % mod;
            }
            result_sum = (result_sum + ccc * current_z[jj]) % mod;
        }
        result_sum = (result_sum + result_sum * A(n, n - i)) % mod;
        current_z = new_z;
    }
    cout << result_sum % mod << "\n";
    return 0;
}

